UPPY_BOOP_V4_GZIP_BASE64
        rm -f "$tmp_path"
        error "Embedded theme picker extraction failed."
        return 1
    fi
    if [[ "$(sha256sum "$tmp_path" | awk '{print $1}')" != "$BOOP_PICKER_SHA256" ]]; then
        rm -f "$tmp_path"
        error "Embedded picker checksum mismatch."
        return 1
    fi
    if [[ -e "$picker_path" ]]; then
        # Keep any user-modified or older bundled copy rather than overwriting it.
        mv -- "$picker_path" "$picker_path.backup.$(date +%Y%m%d-%H%M%S)"
    fi
    chmod 700 "$tmp_path"
    mv -f -- "$tmp_path" "$picker_path"
    printf '%s\n' "$picker_path"
}

launch_terminal_themes() {
    if [[ $EUID -eq 0 ]]; then
        error "Run Terminal Themes as your desktop user, without sudo."
        return 1
    fi
    if ! [[ -t 0 && -t 1 ]]; then
        error "Terminal Themes needs an interactive terminal (a TTY)."
        return 1
    fi
    if $DRY_RUN; then
        info "Dry run: would unpack and open the Boop Terminal Theme Gallery."
        return 0
    fi
    if ! command -v python3 >/dev/null 2>&1; then
        error "Python 3 is required by the picker. Install it with your distro's package manager."
        return 1
    fi
    local picker_path=""
    if ! picker_path="$(boop_picker_install)"; then
        log_msg ERROR "Bundled Terminal Themes failed to extract"
        return 1
    fi
    info "Opening Boop Terminal Theme Gallery..."
    log_msg INFO "Launching Boop Terminal Theme Gallery v4"
    python3 "$picker_path"
    local rc=$?
    if (( rc == 0 )); then
        log_msg INFO "Boop Terminal Theme Gallery exited normally"
    else
        log_msg ERROR "Boop Terminal Theme Gallery exit status $rc"
    fi
    return "$rc"
}

# The UPPY menu is implemented in Bash; it needs no dialog/whiptail/pip
# dependencies and never changes the terminal's default palette.
UPPY_UI_R=$'\033[0m'
UPPY_UI_BORDER=$'\033[38;2;94;114;170m'
UPPY_UI_CYAN=$'\033[38;2;100;227;240m'
UPPY_UI_PURPLE=$'\033[38;2;181;139;255m'
UPPY_UI_GREEN=$'\033[38;2;111;240;172m'
UPPY_UI_DIM=$'\033[38;2;150;168;195m'
UPPY_UI_BOLD=$'\033[1;38;2;235;241;255m'
UPPY_UI_ACTIVE=$'\033[1;38;2;10;22;45;48;2;100;227;240m'
UPPY_UI_NOBG=$'\033[49m'
UPPY_UI_YELLOW=$'\033[38;2;255;204;124m'

UPPY_MENU_LABELS=(
    'Full system update + maintenance'
    'Update only (same as uppy -n)'
    'System health report'
    'Clean packages and caches'
    'Back up packages and settings'
    'Terminal Themes / Boop Gallery'
    'Install workstation applications'
    'Install gaming applications'
    'Configure NFS and iSCSI mounts'
    'Check and repair iSCSI backup'
    'Distro-specific debloat'
    'Self-update UPPY'
    'Exit UPPY'
)
UPPY_MENU_ACTIONS=(update update-only check clean backup terminal-themes workstation gaming mounts repair debloat self-update exit)
UPPY_MENU_COMMANDS=('uppy' 'uppy -n' 'uppy --check' 'uppy --clean' 'uppy --backup' 'uppy --terminal-themes' 'uppy --workstation' 'uppy --gaming' 'uppy --mounts' 'uppy --repair' 'uppy --debloat' 'uppy --self-update' 'q / Esc')
UPPY_MENU_DESCRIPTIONS=(
    'Upgrade your system and Flatpaks.'
    'Run updates directly, then finish.'
    'Read-only system and disk report.'
    'Remove unused packages and caches.'
    'Export your package and system lists.'
    'Preview and apply terminal themes.'
    'Install the configured Flatpak apps.'
    'Install the configured gaming apps.'
    'Set up the saved NAS mount entries.'
    'Check storage, attempt repairs.'
    'Remove selected distro packages.'
    'Update the installed UPPY script.'
    'Leave without changing anything.'
)
UPPY_MENU_WARNINGS=(
    'Optional maintenance asks before running.'
    'No menu. No optional tasks. No self-install.'
    'Does not modify system settings.'
    'Package removal may be irreversible.'
    'Saved under ~/uppy-backups.'
    'Runs as desktop user; Python 3 needed.'
    'Uses Flathub; network required.'
    'Uses Flathub; network required.'
    'May modify /etc/fstab (backup made).'
    'Repair may unmount volumes.'
    'Review the package removal prompt.'
    'Requires UPPY_UPDATE_URL to be set.'
    'No changes performed.'
)

uppy_menu_cleanup() {
    if [[ "${UPPY_PICKER_ACTIVE:-false}" == true ]]; then
        printf '\033[0m\033[?25h\033[?1049l'
        UPPY_PICKER_ACTIVE=false
    fi
}

uppy_ui_repeat() {
    local ch="$1" count="$2" i
    for ((i=0; i<count; i++)); do printf '%s' "$ch"; done
}

uppy_ui_line() {
    local left="$1" right="${2:-}" accent="${3:-$UPPY_UI_R}"
    if (( UPPY_UI_WIDE )); then
        printf '%s│%s  %s%-*.*s%s %s│%s %s%-*.*s%s  %s│%s\n' \
            "$UPPY_UI_BORDER" "$UPPY_UI_R" "$accent" "$UPPY_UI_LEFT" "$UPPY_UI_LEFT" "$left" "$UPPY_UI_R" \
            "$UPPY_UI_BORDER" "$UPPY_UI_R" "$UPPY_UI_DIM" "$UPPY_UI_RIGHT" "$UPPY_UI_RIGHT" "$right" "$UPPY_UI_R" \
            "$UPPY_UI_BORDER" "$UPPY_UI_R"
    else
        printf '%s│%s %s%-*.*s%s %s│%s\n' \
            "$UPPY_UI_BORDER" "$UPPY_UI_R" "$accent" "$UPPY_UI_LEFT" "$UPPY_UI_LEFT" "$left" "$UPPY_UI_R" \
            "$UPPY_UI_BORDER" "$UPPY_UI_R"
    fi
}

uppy_ui_rule() {
    local left="$1" right="$2"
    printf '%s%s' "$UPPY_UI_BORDER" "$left"
    uppy_ui_repeat '═' "$(( UPPY_UI_WIDTH-2 ))"
    printf '%s%s\n' "$right" "$UPPY_UI_R"
}

uppy_menu_draw() {
    local selected="$1" size cols rows width label prefix rline entry n act
    size="$(stty size 2>/dev/null || printf '24 80')"
    rows="${size%% *}"; cols="${size##* }"
    [[ "$cols" =~ ^[0-9]+$ ]] || cols=80
    (( cols>=42 )) || cols=42
    UPPY_UI_WIDTH=$((cols>118 ? 118 : cols-1))
    UPPY_UI_WIDE=0
    if (( UPPY_UI_WIDTH>=100 )); then
        UPPY_UI_WIDE=1
        UPPY_UI_RIGHT=43
        UPPY_UI_LEFT=$((UPPY_UI_WIDTH-UPPY_UI_RIGHT-9))
    else
        UPPY_UI_LEFT=$((UPPY_UI_WIDTH-4))
        UPPY_UI_RIGHT=0
    fi
    local host="${HOSTNAME:-$(hostname 2>/dev/null || printf 'local')}"
    host="${host:0:22}"
    local distro="${PRETTY_NAME:-${ID:-Linux}}"
    distro="${distro:0:27}"
    local ascii_command="${UPPY_MENU_COMMANDS[selected]}"
    local r=(
      'SELECTED ACTION'
      ''
      "$(printf '%02d  %s' "$((selected+1))" "${UPPY_MENU_LABELS[selected]}")"
      ''
      "${UPPY_MENU_DESCRIPTIONS[selected]}"
      ''
      'QUICK COMMAND'
      "$ascii_command"
      ''
      'NOTES'
      "${UPPY_MENU_WARNINGS[selected]}"
      ''
      "System: $distro"
    )
    if [[ -n "${NO_COLOR:-}" ]] || [[ "${TERM:-}" == dumb ]]; then
        UPPY_UI_BORDER=''; UPPY_UI_CYAN=''; UPPY_UI_PURPLE=''; UPPY_UI_GREEN=''
        UPPY_UI_DIM=''; UPPY_UI_BOLD=''; UPPY_UI_ACTIVE=''; UPPY_UI_YELLOW=''; UPPY_UI_R=''
    fi
    printf '\033[H\033[2J'
    uppy_ui_rule '╔' '╗'
    if (( UPPY_UI_WIDE )); then
        uppy_ui_line "UPPY  v${UPPY_VERSION}   /   CONTROL CENTRE" "ARCH / FEDORA / DEBIAN  |  $host" "$UPPY_UI_BOLD"
        uppy_ui_line 'System updates  |  tools  |  terminal appearance' 'Use the arrows and Enter to select.' "$UPPY_UI_CYAN"
    else
        uppy_ui_line "UPPY v${UPPY_VERSION}  /  CONTROL CENTRE" '' "$UPPY_UI_BOLD"
        uppy_ui_line 'System updates / tools / appearance' '' "$UPPY_UI_CYAN"
    fi
    uppy_ui_rule '╠' '╣'
    if (( UPPY_UI_WIDE )); then
        uppy_ui_line '    ACTIONS' '    LIVE SELECTION DETAILS' "$UPPY_UI_PURPLE"
    else
        uppy_ui_line '    ACTIONS  /  UP-DOWN TO NAVIGATE' '' "$UPPY_UI_PURPLE"
    fi
    for ((n=0; n<${#UPPY_MENU_LABELS[@]}; n++)); do
        if (( n==selected )); then
            printf -v entry '  > %02d  %s' "$((n+1))" "${UPPY_MENU_LABELS[n]}"
            accent="$UPPY_UI_ACTIVE"
        else
            printf -v entry '    %02d  %s' "$((n+1))" "${UPPY_MENU_LABELS[n]}"
            accent="$UPPY_UI_R"
        fi
        rline="${r[n]:-}"
        uppy_ui_line "$entry" "$rline" "$accent"
    done
    uppy_ui_rule '╠' '╣'
    if (( UPPY_UI_WIDE )); then
        uppy_ui_line '  UP/DOWN  Navigate   ENTER  Run   Q  Exit' 'TIP: uppy -n skips this menu.' "$UPPY_UI_GREEN"
    else
        uppy_ui_line '  UP/DOWN Move   ENTER Run   Q Exit' '' "$UPPY_UI_GREEN"
        uppy_ui_line "  Selected: ${UPPY_MENU_COMMANDS[selected]}" '' "$UPPY_UI_DIM"
    fi
    uppy_ui_rule '╚' '╝'
}

uppy_menu_read_key() {
    local k="" tail=""
    if ! IFS= read -r -s -n 1 k; then
        UPPY_MENU_KEY='quit'; return 0
    fi
    if [[ "$k" == $'\033' ]]; then
        IFS= read -r -s -n 1 -t 0.15 tail || true
        if [[ "$tail" == '[' || "$tail" == 'O' ]]; then
            local arrow=""
            IFS= read -r -s -n 1 -t 0.15 arrow || true
            case "$arrow" in
                A) UPPY_MENU_KEY='up' ;; B) UPPY_MENU_KEY='down' ;;
                H) UPPY_MENU_KEY='home' ;; F) UPPY_MENU_KEY='end' ;;
                *) UPPY_MENU_KEY='none' ;;
            esac
        else
            UPPY_MENU_KEY='quit'
        fi
    elif [[ "$k" == '' ]]; then
        UPPY_MENU_KEY='select'
    else
        case "$k" in
            k|K) UPPY_MENU_KEY='up' ;;
            j|J) UPPY_MENU_KEY='down' ;;
            q|Q) UPPY_MENU_KEY='quit' ;;
            [1-9]) UPPY_MENU_KEY="digit:$k" ;;
            *) UPPY_MENU_KEY='none' ;;
        esac
    fi
}

uppy_menu_pick() {
    local selected=0
    UPPY_MAIN_MENU_ACTION='exit'
    UPPY_PICKER_ACTIVE=true
    printf '\033[?1049h\033[?25l'
    trap 'exit 130' INT
    trap 'exit 143' TERM
    while true; do
        uppy_menu_draw "$selected"
        uppy_menu_read_key
        case "$UPPY_MENU_KEY" in
            up) selected=$(((selected+${#UPPY_MENU_LABELS[@]}-1)%${#UPPY_MENU_LABELS[@]})) ;;
            down) selected=$(((selected+1)%${#UPPY_MENU_LABELS[@]})) ;;
            home) selected=0 ;;
            end) selected=$((${#UPPY_MENU_LABELS[@]}-1)) ;;
            digit:*)
                local d="${UPPY_MENU_KEY#digit:}"
                if ((d<=${#UPPY_MENU_LABELS[@]})); then selected=$((d-1)); fi
                ;;
            select)
                UPPY_MAIN_MENU_ACTION="${UPPY_MENU_ACTIONS[selected]}"
                break
                ;;
            quit) UPPY_MAIN_MENU_ACTION='exit'; break ;;
        esac
    done
    uppy_menu_cleanup
    trap - INT TERM
}

uppy_menu_run_tool() {
    local action="$1"
    case "$action" in
        terminal-themes) launch_terminal_themes ;;
        check) uppy_check ;;
        backup) uppy_backup ;;
        clean)
            if ask 'Remove orphaned packages and clean caches?'; then
                start_sudo_session && uppy_clean
            fi
            ;;
        workstation) start_sudo_session && install_workstation_apps ;;
        gaming) start_sudo_session && install_gaming_apps ;;
        mounts)
            if ask 'Configure NFS mounts and check iSCSI storage?'; then
                start_sudo_session && install_dependencies && configure_nfs_mounts && check_iscsi_backup
            fi
            ;;
        repair)
            if ask 'Check and potentially repair the iSCSI volume?'; then
                start_sudo_session && check_iscsi_backup
            fi
            ;;
        debloat)
            if ask 'Open distro-specific package debloat?'; then
                start_sudo_session && nobara_debloat
            fi
            ;;
        self-update) start_sudo_session && self_update ;;
        *) error "Unsupported menu action: $action"; return 1 ;;
    esac
}

uppy_interactive_menu() {
    local UPPY_MAIN_MENU_ACTION='exit'
    local rc=0
    while true; do
        uppy_menu_pick
        case "$UPPY_MAIN_MENU_ACTION" in
            exit) echo 'Goodbye.'; return 1 ;;
            update) return 0 ;;
            update-only) AUTO_SKIP_OPTIONAL=true; return 0 ;;
            *)
                printf '\n'
                if uppy_menu_run_tool "$UPPY_MAIN_MENU_ACTION"; then
                    log_msg INFO "Menu action $UPPY_MAIN_MENU_ACTION completed"
                else
                    rc=$?
                    warn "Menu action $UPPY_MAIN_MENU_ACTION exited with code $rc"
                    log_msg ERROR "Menu action $UPPY_MAIN_MENU_ACTION failed ($rc)"
                fi
                stop_sudo_session
                printf '\n'
                read -r -p 'Press Enter to return to UPPY (Q to quit): ' reply || reply=q
                if [[ "$reply" == [Qq] ]]; then echo 'Goodbye.'; return 1; fi
                ;;
        esac
    done
}

main() {
    setup_logging "$@"

    # Run the theme picker before sudo/session setup or self-installation;
    # appearance settings belong to the signed-in desktop user.
    if [[ "$RUN_ONLY" == "terminal-themes" ]]; then
        launch_terminal_themes
        return $?
    fi
    # With no arguments, show the interactive picker. -n deliberately bypasses
    # the picker and runs only system package + Flatpak updates.
    if (( ORIGINAL_ARGUMENT_COUNT == 0 )) || $FORCE_MENU; then
        if [[ -t 0 && -t 1 ]] && ! $AUTO_SKIP_OPTIONAL; then
            if ! uppy_interactive_menu; then return 0; fi
        fi
    fi

    if $AUTO_SKIP_OPTIONAL && [[ -z "$RUN_ONLY" ]] && ! $AUTO_REBOOT && ! $AUTO_SHUTDOWN; then
        start_sudo_session
        echo "Running UPPY quick update (-n): no menu or optional maintenance."
        update_system
        update_flatpaks
        echo "Update finished."
        return 0
    fi

    start_sudo_session
    install_self

    if $DRY_RUN; then
        warn "Dry-run mode enabled: privileged commands will be printed instead of executed."
    fi
    echo "Detected distro type: $DISTRO"

    run_only_mode || true

    update_system
    update_flatpaks

    if ! $AUTO_SKIP_OPTIONAL && ask "Run optional maintenance tasks?" 5; then

        if ask "Run all optional tasks?"; then
            ask "Create UPPY backup first?" && uppy_backup
            ask "Install NFS/CIFS utilities?" && install_dependencies
            [[ "$ID" == "cachyos" ]] && cachyos_cleanup_and_gaming
            [[ "$DISTRO" == "nobara" ]] && nobara_debloat
            configure_nfs_mounts
            check_iscsi_backup
            remove_unused_packages
            clean_package_cache
            clean_flatpak_runtimes
            ask "Install workstation applications?" && install_workstation_apps
            ask "Install gaming applications?" && install_gaming_apps
        else
            ask "Create UPPY backup first?" && uppy_backup
            ask "Install NFS/CIFS utilities?" && install_dependencies
            [[ "$ID" == "cachyos" ]] && ask "Run CachyOS cleanup & gaming setup?" && cachyos_cleanup_and_gaming
            [[ "$DISTRO" == "nobara" ]] && ask "Run Nobara debloat?" && nobara_debloat
            ask "Configure NFS mounts?" && configure_nfs_mounts
            ask "Check & repair iSCSI backup?" && check_iscsi_backup
            ask "Remove orphan packages?" && remove_unused_packages
            ask "Clean package caches?" && clean_package_cache
            ask "Clean unused Flatpak runtimes?" && clean_flatpak_runtimes
            ask "Install workstation applications?" && install_workstation_apps
            ask "Install gaming applications?" && install_gaming_apps
        fi
    fi

    echo
    echo "Finished."

    if $AUTO_REBOOT; then
        echo
        echo "Rebooting in 5 seconds..."
        sleep 5
        run_sudo reboot
    elif $AUTO_SHUTDOWN; then
        echo
        echo "Shutting down in 5 seconds..."
        sleep 5
        if command -v systemctl >/dev/null 2>&1; then
            run_sudo systemctl poweroff
        else
            run_sudo shutdown -h now
        fi
    fi
}

main "$@"
